function findOrder(numCourses: number, prerequisites: number[][]): number[] {
  // Ребро b -> a; indegree[a] — сколько курсов нужно пройти до a
  const graph: number[][] = Array.from({ length: numCourses }, () => []);
  const indegree = new Array<number>(numCourses).fill(0);
  for (const [a, b] of prerequisites) {
    graph[b].push(a);
    indegree[a]++;
  }

  // Начинаем с курсов без зависимостей
  const queue: number[] = [];
  for (let c = 0; c < numCourses; c++) {
    if (indegree[c] === 0) queue.push(c);
  }

  // queue одновременно и очередь, и ответ: курсы в ней лежат в порядке прохождения.
  // head — указатель на начало очереди (без дорогого shift)
  for (let head = 0; head < queue.length; head++) {
    const course = queue[head];
    for (const next of graph[course]) {
      // Курс course пройден — у next стало на одну зависимость меньше
      indegree[next]--;
      if (indegree[next] === 0) queue.push(next);
    }
  }

  // Если какие-то курсы так и не освободились — они в цикле
  return queue.length === numCourses ? queue : [];
}

// Время: O(V + E)
// Память: O(V + E) — граф, полустепени и очередь
